import numpy as np
P=df['P'].values; y=df['dP_dt'].values; t=df['t'].values
for lo in np.arange(0.5,12,1.5):
    m=(t>=lo)&(t<lo+1.5)
    if m.sum()<10: continue
    for deg in [2,3,4]:
        A=np.column_stack([P[m]**k for k in range(deg+1)])
        cc=np.linalg.lstsq(A,y[m],rcond=None)[0]
        r=y[m]-A@cc
        if deg==2: print(round(lo,1), m.sum(), 'rms2', round(np.sqrt(np.mean(r**2)),4), end=' ')
        elif deg==3: print('rms3', round(np.sqrt(np.mean(r**2)),4), 'c3', round(cc[3],3), end=' ')
        else: print('rms4', round(np.sqrt(np.mean(r**2)),4), 'c4', round(cc[4],3))
